`// acceptance 010c-setup
// @param gain label:"Gain" min:0 max:2 default:0.25
struct FxUniforms {
u_resolution: vec2<f32>,
u_time: f32,
u_frame: f32,
gain: f32,
}
@group(0) @binding(0) var u_input: texture_2d<f32>;
@group(0) @binding(1) var u_sampler: sampler;
@group(0) @binding(2) var<uniform> fx: FxUniforms;
@fragment
fn main(@location(0) v_uv: vec2<f32>) -> @location(0) vec4<f32> {
return vec4<f32>(fx.gain,0.0,0.0,1.0);
}
`;0
